import {realismFor,materialPrice} from './realism.js';
import {MATERIALS,FILAMENT_COLORS,colorFor,filamentStock,stockNeeds,quoteBasket,stockCapacity,masteryInfo} from './model.js';
import {normalizeLife} from './lifestyle.js';
const decimal=n=>n.toLocaleString('fr-FR',{maximumFractionDigits:2});
const euro=n=>n.toLocaleString('fr-FR',{style:'currency',currency:'EUR'}),num=n=>Math.round(n).toLocaleString('fr-FR');
const dot=c=>`<i class="filament-dot" style="--filament:${c}"></i>`;
export function stockGlance(s,basket){
 const needs=stockNeeds(s),missing=needs.filter(n=>n.missing>0),stock=new Map();for(const l of s.inventory){const k=l.material+':'+l.colorId;if(!stock.has(k))stock.set(k,{...l});else stock.get(k).grams+=l.grams;}
 const q=quoteBasket(basket,s.settings),arrivals=new Set(s.supplies.map(l=>l.batchId||l.id)).size;
 return `<div class="stock-glance-head"><b>Les bobines</b><span>${num(s.stock.pla+s.stock.petg)} g</span><button data-action="quick-stock" aria-label="Acheter des bobines" title="Achat rapide">＋</button></div><div class="visible-filaments">${[...stock.values()].map(l=>`<button data-action="stock-color" data-material="${l.material}" data-color="${l.colorId==='legacy'?'natural':l.colorId}" title="${MATERIALS[l.material].name} ${colorFor(l.colorId).name} · ${num(l.grams)} g">${dot(colorFor(l.colorId).hex)}<b>${l.material.toUpperCase()}</b><span>${colorFor(l.colorId).name.replace(' · ancien stock','')} · ${num(l.grams)} g</span></button>`).join('')||'<small>Les étagères sont vides.</small>'}</div>${missing.length?`<button class="stock-alert" data-action="restock-needed">${dot('#c77f61')} ${missing.length} couleur(s) manquante(s) · préparer le panier</button>`:`<span class="stock-ok">${needs.length?'✓ Matière disponible ou en route':'Les premières idées attendent ton fil.'}</span>`}<div class="stock-glance-actions"><button data-action="quick-stock">${q.ok?'Panier · '+q.qty+' bobine(s) · '+euro(q.total):'Acheter des bobines'}</button>${arrivals?`<span>↗ ${arrivals} livraison(s)</span>`:''}</div><button class="energy-glance ${s.energy.bills.some(b=>!b.paid)?'due':''}" data-action="energy"><b>ϟ</b><span>${s.energy.bills.some(b=>!b.paid)?'Facture électrique à régler':decimal(s.energy.unbilledKWh)+' kWh · mois en cours'}</span><b>${euro(s.energy.unbilledCost+s.energy.bills.filter(b=>!b.paid).reduce((a,b)=>a+b.amount,0))}</b></button>`;
}
export function stockInterface(s,basket,draft={material:'pla',colorId:'natural',qty:1}){
 const q=quoteBasket(basket,s.settings),needs=stockNeeds(s),color=colorFor(draft.colorId),pending=s.supplies.filter(l=>l.kind==='filament').reduce((n,l)=>n+l.qty,0),occupied=s.inventory.reduce((n,l)=>n+Math.ceil(l.grams/1000),0),capacity=stockCapacity(s)/1000;
 const groups=new Map();for(const l of s.supplies){const key=l.batchId||l.id;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(l);}
 return `<div class="stock-intro"><div><span class="eyebrow">TOUT SOUS LA MAIN</span><h2>Du fil. Les bonnes couleurs.</h2><p>${occupied} bobine(s) rangée(s), ${pending} en route · ${capacity} places au total.</p></div></div>${needs.length?`<div class="needs-board"><div><b>Pour les commandes confirmées</b><button class="text-button" data-action="restock-needed">Compléter les manques</button></div>${needs.map(n=>`<div class="need-line">${dot(colorFor(n.colorId).hex)}<span><b>${MATERIALS[n.material].name} · ${colorFor(n.colorId).name}</b><small>${num(n.grams)} g requis · ${num(n.available)} g disponibles${n.incoming?' · '+num(n.incoming)+' g en route':''}</small></span>${n.missing>0?`<button data-action="add-needed" data-material="${n.material}" data-color="${n.colorId}" data-grams="${n.missing}" aria-label="Ajouter ${colorFor(n.colorId).name} au panier">＋ ${num(n.missing)} g</button>`:'<em>✓ Prévu</em>'}</div>`).join('')}</div>`:''}
 <section class="quick-supplier"><div class="supplier-title"><h3>Choisis tes bobines</h3><span>1 bobine = 1 kg</span></div><div class="material-choices">${Object.entries(MATERIALS).map(([id,m])=>`<button data-action="cart-material" data-material="${id}" aria-pressed="${draft.material===id}">${m.name} <small>${euro(materialPrice(s.settings,id))} / kg</small></button>`).join('')}</div><div class="supplier-colors" aria-label="Couleur du filament">${FILAMENT_COLORS.map(c=>`<button style="--filament:${c.hex}" data-action="cart-color" data-color="${c.id}" aria-label="Filament ${c.name}" aria-pressed="${draft.colorId===c.id}" title="${c.name}"><i></i><span>${c.name}</span></button>`).join('')}</div><div class="supplier-add"><span>${dot(color.hex)} <b>${MATERIALS[draft.material].name} · ${color.name}</b></span><div class="quantity-stepper"><button data-action="cart-qty" data-delta="-1" aria-label="Une bobine de moins">−</button><b>${draft.qty}</b><button data-action="cart-qty" data-delta="1" aria-label="Une bobine de plus">＋</button></div><button class="button primary" data-action="cart-add">Ajouter · ${euro(materialPrice(s.settings,draft.material)*draft.qty)}</button></div></section>
 <section class="supplier-basket"><div class="supplier-title"><h3>Ta livraison groupée</h3><small>Un seul port pour tout le panier.</small></div>${q.ok?`<div class="basket-lines">${q.lines.map(l=>`<div>${dot(colorFor(l.colorId).hex)}<span><b>${MATERIALS[l.item].name} · ${colorFor(l.colorId).name}</b><small>${l.qty} × 1 kg</small></span><b>${euro(l.unitPrice*l.qty)}</b><button data-action="cart-remove" data-material="${l.item}" data-color="${l.colorId}" aria-label="Retirer ${MATERIALS[l.item].name} ${colorFor(l.colorId).name}">−</button></div>`).join('')}</div><div class="basket-price"><span>Bobines <b>${euro(q.subtotal)}</b></span><span>Port commun <b>${euro(q.shipping)}</b></span>${q.qty>1?`<small>${euro(q.savedShipping)} de port économisés par rapport à ${q.qty} achats séparés.</small>`:''}<strong>Total <b>${euro(q.total)}</b></strong></div><button class="button primary checkout-basket" data-action="cart-checkout">Commander ${q.qty} bobine(s) · ${euro(q.total)}</button><p class="fine-print">Débit à la commande. Préparation de ${realismFor(s).supplierHours} h puis livraison au prochain créneau ouvré à 10 h. La matière devient utilisable à réception.</p>`:'<p class="empty-line">Ajoute une couleur ou complète automatiquement les manques des commandes.</p>'}</section>
 ${groups.size?`<section class="deliveries-compact"><h3>Sur la route</h3>${[...groups.values()].map(group=>`<div><b>↗ Jour ${Math.floor(group[0].due/1440)+1} à 10 h</b><span>${group.map(l=>l.kind==='filament'?`${l.qty} × ${MATERIALS[l.item].name} ${colorFor(l.colorId).name}`:'Pièce de rechange').join(' · ')}</span></div>`).join('')}</section>`:''}<div class="stock-real-inventory"><h3>Réellement dans l’atelier</h3>${s.inventory.length?`<div class="inventory-rolls">${s.inventory.map(l=>`<div><span class="little-spool" style="--filament:${colorFor(l.colorId).hex};--fill:${Math.max(.12,Math.sqrt(Math.min(1000,l.grams)/1000))}"></span><b>${l.material.toUpperCase()} · ${colorFor(l.colorId).name}</b><small>${num(l.grams)} g</small></div>`).join('')}</div>`:'<p>Le rayonnage est vide.</p>'}</div>`;
}
export function lifeForm(s,first=false){const p=normalizeLife(s.life),mode=p.configured?p.mode:'job',hm=n=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');return `<form id="life-form" class="life-form"><p class="modal-lead">${first?'Avant de commencer, choisis le rythme de ta vie et de ton atelier.':'Ton emploi, ton sommeil et tes vraies disponibilités.'} Les imprimantes peuvent continuer sans toi. Le salaire extérieur ne rentre pas dans la caisse de l’atelier.</p><div class="life-mode"><label><input type="radio" name="life-mode" value="job" ${mode==='job'?'checked':''}> En parallèle d’un emploi</label><label><input type="radio" name="life-mode" value="fulltime" ${mode==='fulltime'?'checked':''}> L’atelier à temps plein</label></div><section id="employment-fields" ${mode==='fulltime'?'hidden':''}><h3>Quand travailles-tu ailleurs ?</h3><div class="time-fields"><label>Début de travail<input type="time" name="workStart" value="${hm(p.workStart)}" required></label><label>Fin de travail<input type="time" name="workEnd" value="${hm(p.workEnd)}" required></label><label>Trajet aller<input type="number" name="commute" min="0" max="180" value="${p.commute}"><small>minutes, comptées aussi au retour</small></label></div><div class="week-choices">${['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'].map((day,i)=>`<label>${day}<select name="day-${i}" aria-label="${day}"><option value="off" ${!p.workDays.includes(i)?'selected':''}>Libre</option><option value="office" ${p.workDays.includes(i)&&!p.remoteDays.includes(i)?'selected':''}>Sur place</option><option value="remote" ${p.remoteDays.includes(i)?'selected':''}>Télétravail</option></select></label>`).join('')}</div><div class="time-fields"><label>Interventions en télétravail<select name="remoteBudget">${[15,30,45,60,90].map(n=>`<option value="${n}" ${p.remoteBudget===n?'selected':''}>${n} min maximum / jour</option>`).join('')}</select><small>Confirmer une demande : 3 min. Charger une machine : 10 min. Conception longue, finition et entretien attendent ton temps libre.</small></label><label>Temps d’atelier disponible<select name="workshopBudget">${[120,180,240,360,480].map(n=>`<option value="${n}" ${p.workshopBudget===n?'selected':''}>${n/60} h maximum / jour</option>`).join('')}</select><small>Inclut les interventions en télétravail.</small></label></div></section><section><h3>Le sommeil compte aussi</h3><div class="time-fields"><label>Je me couche à<input type="time" name="sleepStart" value="${hm(p.sleepStart)}" required></label><label>Je me réveille à<input type="time" name="sleepEnd" value="${hm(p.sleepEnd)}" required></label></div><p class="fine-print">Au travail extérieur et pendant le sommeil, les tâches manuelles attendent. Tu peux toujours observer l’atelier, consulter les menus, changer la vitesse et ouvrir les paramètres.</p></section><section><h3>À quelle vitesse veux-tu jouer ?</h3><div class="time-fields"><label>Quand je suis disponible<select name="normalSpeed" aria-label="Quand je suis disponible">${[60,240,480,1440].map(n=>`<option value="${n}" ${p.normalSpeed===n?'selected':''}>×${n} · 1 min = ${n/60} h${n===240?' · conseillé':''}</option>`).join('')}</select></label><label>Travail extérieur et sommeil<select name="awaySpeed" aria-label="Travail extérieur et sommeil">${[60,240,480,1440,7200].map(n=>`<option value="${n}" ${p.awaySpeed===n?'selected':''}>×${n} · 1 min = ${n/60} h${n===480?' · conseillé':''}</option>`).join('')}</select></label></div><p class="fine-print">La vitesse reste modifiable à tout moment. Par défaut, l’atelier continue à tourner et retrouve sa vitesse normale à ton retour ou au réveil. À temps plein : atelier du lundi au vendredi, 8 h 30–12 h 30 et 13 h 30–17 h 30.</p></section><section class="idle-preferences"><h3>À regarder vivre, à ton rythme</h3><label class="switch-row"><span><b>Accélérer automatiquement pendant les absences</b><small>Tu peux toujours choisir une autre vitesse avec les boutons, même la nuit.</small></span><input type="checkbox" name="autoSpeed" ${p.autoSpeed?'checked':''}></label><label class="switch-row"><span><b>Mettre en pause à mon retour</b><small>Facultatif : sinon le jeu continue, pour le laisser tourner à côté.</small></span><input type="checkbox" name="pauseOnReturn" ${p.pauseOnReturn?'checked':''}></label><label class="switch-row"><span><b>Continuer en arrière-plan</b><small>La simulation progresse tant que la page reste ouverte. Le son se coupe lorsque l’onglet est masqué.</small></span><input type="checkbox" name="backgroundProgress" ${p.backgroundProgress?'checked':''}></label></section><p id="life-error" role="status" class="danger"></p><div class="modal-actions"><button type="submit" class="button primary">${first?'Commencer mon aventure':'Enregistrer mon rythme'}</button></div></form>`;}
export function masteryPanel(s){const m=masteryInfo(s);return `<div class="mastery-card"><span class="eyebrow">LE GESTE S’AFFINE</span><h3>Maîtrise · ${m.label}</h3><div class="mastery-track"><i style="width:${m.progress}%"></i></div><p>${m.xp} points${m.next?' / '+m.next+' au prochain palier':' · niveau maximal'} · ${s.mastery.prints} impression(s) réussie(s)</p><div><span>Temps de préparation <b>−${Math.round(m.timeBonus*100)} %</b></span><span>Risque de raté <b>−${(m.failureBonus*100).toFixed(1)} point(s)</b></span></div><small>Les impressions, les réparations et les essais font progresser. La vitesse physique des machines reste la même.</small><button class="button secondary small" data-action="practice">S’exercer · 45 min et 25 g</button></div>`;}
export function audioPanel(audio){const p=audio.prefs;return `<div class="audio-intro"><span>♫</span><p>Le doux bruit des idées.<small>Imprimantes, papier, colis et petites notes. Les sons gardent leur rythme, même en accéléré.</small></p></div><label class="switch-row"><span><b>Les sons de l’atelier</b><small id="audio-status">${audio.status()}</small></span><input type="checkbox" data-audio="enabled" ${p.enabled?'checked':''}></label>${[['master','Volume général'],['effects','Actions et notifications'],['ambience','Ambiance et imprimantes']].map(([key,name])=>`<label class="audio-slider">${name}<input type="range" min="0" max="100" value="${p[key]}" data-audio="${key}" aria-label="${name}"><output data-audio-output="${key}">${p[key]} %</output></label>`).join('')}<label class="switch-row"><span><b>Quelques notes de musique</b><small>Une mélodie légère, espacée et facultative.</small></span><input type="checkbox" data-audio="music" ${p.music?'checked':''}></label><div class="modal-actions"><button class="button secondary" data-action="test-audio">Écouter un aperçu</button><button class="button primary" data-action="close-modal">C’est réglé</button></div><p class="fine-print">M pour couper ou réactiver. Réglages conservés sur cet appareil. Le son se coupe quand tu quittes l’onglet.</p>`;}

export function energyPanel(s){const pending=s.energy.bills.filter(b=>!b.paid),owed=pending.reduce((a,b)=>a+b.amount,0);return `<div class="energy-summary"><div><span>Mois en cours · consommation</span><strong>${decimal(s.energy.unbilledKWh)} kWh</strong></div><div><span>Coût à facturer</span><strong>${euro(s.energy.unbilledCost)}</strong></div></div><p class="energy-footnote">Tarif actuel : ${euro(s.settings.electricity)} / kWh. Un poste compact consomme en moyenne 120 W pendant l’impression, un fermé 160 W, un pro 200 W. Seules les minutes d’impression effective sont facturées ; les machines inactives sont considérées éteintes. Les repères sont des hypothèses de simulation.</p><label class="switch-row"><span><b>Payer automatiquement à l’échéance</b><small>Facture tous les 30 jours, règlement sous 7 jours si la caisse le permet.</small></span><input type="checkbox" data-setting="autoPayEnergy" ${s.settings.autoPayEnergy?'checked':''}></label>${pending.length?`<h3>${euro(owed)} à régler</h3>`:'<p class="empty-line">Aucune facture en attente.</p>'}${s.energy.bills.slice(-12).reverse().map(b=>`<article class="energy-bill"><div><b>Facture du jour ${Math.floor(b.issued/1440)+1} · ${euro(b.amount)}</b><small>${decimal(b.kWh)} kWh · échéance jour ${Math.floor(b.due/1440)+1}${b.paid?' · réglée au jour '+(Math.floor(b.paidAt/1440)+1):''}</small></div>${b.paid?'<span class="pill green">Réglée</span>':`<button class="button primary" data-action="pay-energy" data-id="${b.id}">Payer ${euro(b.amount)}</button>`}</article>`).join('')}<p class="energy-footnote">Le coût consommé est déjà compté dans le résultat de chaque journée. Le paiement de la facture fait seulement baisser la caisse : il ne crée pas une seconde charge. Les anciennes parties commencent un nouveau relevé, sans refacturer leur consommation passée.</p>`;}
